xml.Script:
        if not VarExists('Colors') then begin
            clSilver := 'B0B8C0';

            Colors[0] := clSilver;
            Colors[1] := clSilver;
            Colors[2] := clSilver;
            Colors[3] := clSilver;
            Colors[4] := clSilver;
            Colors[5] := clSilver;
        end;

        include 'Figures\Scripts\Cube_Coordinates.inc';

        for i := 0 to 7 do begin
            Vx[i] := Vx[i] + 0.34 * W;
            Vy[i] := Vy[i] - 0.36 * W;
            Vz[i] := Vz[i] + 0.30 * W;
        end;
